class RemoteWrapper:
    def __init__(self, target, opts=None):
        self._target = target
        self._opts = opts or {}
    def options(self, **kw):
        return RemoteWrapper(self._target, {**self._opts, **kw})
    def remote(self, *a, **kw):
        if isinstance(self._target, type):
            name = self._opts.get('name')
            ns = self._opts.get('namespace', 'default')
            if name and (ns, name) in _named_actors:
                if self._opts.get('get_if_exists'):
                    return _named_actors[(ns, name)]
                raise ValueError(f'Actor {name} already exists')
            inst = self._target(*a, **kw)
            h = ActorHandleProxy(inst)
            if name:
                _named_actors[(ns, name)] = h
            return h
        res = self._target(*a, **kw)
        if inspect.iscoroutine(res):
            try:
                asyncio.get_running_loop()
                return asyncio.ensure_future(res)
            except RuntimeError:
                res = asyncio.run(res)
        return LocalRef(res)

class ActorHandleProxy:
    def __init__(self, inst):
        self._inst = inst
        for name in dir(inst):
            if not name.startswith('__'):
                attr = getattr(inst, name)
                if callable(attr):
                    setattr(self, name, RemoteWrapper(attr))

